int main()
{
    int ok = 1;
    int owner = 1;
    CBuildingSimDefinition sim = { 1, &owner };
    CTCShopSign sign = { false };
    CTCBuildingGuarded guarded = { false };
    CThing hero = { 1, 0, false, 0, 0, 0 };
    CThing house = { 3, 0, false, &sign, &guarded, &sim };
